    'bn': '🎯 **বাচ্চা দেওয়ার ব্যবধান ১৩-১৪ মাস রাখুন** — এটাই লাভের আসল চাবিকাঠি। বাচ্চা দেওয়ার ৬০-৯০ দিনের মধ্যে আবার গর্ভবতী করান।',
    'gu': '🎯 **વિયાણનો ગાળો 13-14 મહિના રાખો** — આ જ નફાની અસલી ચાવી છે. વિયાણના 60-90 દિવસની અંદર ફરી ફેળવો.',
    'pa': '🎯 **ਵਿਆਂਤ ਦਾ ਅੰਤਰ 13-14 ਮਹੀਨੇ ਰੱਖੋ** — ਇਹੋ ਮੁਨਾਫ਼ੇ ਦੀ ਅਸਲੀ ਚਾਬੀ ਹੈ। ਵਿਆਉਣ ਦੇ 60-90 ਦਿਨਾਂ ਦੇ ਅੰਦਰ ਦੁਬਾਰਾ ਗੱਭਣ ਕਰਵਾਓ।',
    'mr': '🎯 **वेतातील अंतर 13-14 महिने ठेवा** — हीच नफ्याची खरी गुरुकिल्ली आहे. व्यायानंतर 60-90 दिवसांच्या आत पुन्हा गाभण करा.',
    'bho': '🎯 **बियाए के अंतर 13-14 महीना राखीं** — इहे मुनाफा के असली चाबी बा। बियाए के 60-90 दिन के अंदर दोबारा गाभिन कराईं।',
  },
  '🐄 **राष्ट्रीय गोकुल मिशन (RGM)** — देसी नस्ल सुधार, मुफ़्त/सस्ता कृत्रिम गर्भाधान और सेक्स-सॉर्टेड वीर्य पर अनुदान।': {
    'ta': '🐄 **தேசிய கோகுல் இயக்கம் (RGM)** — நாட்டு இன மேம்பாடு, இலவச/மலிவு செயற்கை முறை மற்றும் பாலினம் பிரிக்கப்பட்ட விந்தணு மானியம்.',
    'te': '🐄 **జాతీయ గోకుల్ మిషన్ (RGM)** — దేశీ జాతి అభివృద్ధి, ఉచిత/చౌక కృత్రిమ గర్భధారణ మరియు సెక్స్-సార్టెడ్ వీర్యంపై రాయితీ.',
    'kn': '🐄 **ರಾಷ್ಟ್ರೀಯ ಗೋಕುಲ ಮಿಷನ್ (RGM)** — ದೇಸಿ ತಳಿ ಸುಧಾರಣೆ, ಉಚಿತ/ಅಗ್ಗದ ಕೃತಕ ಗರ್ಭಧಾರಣೆ ಮತ್ತು ಲಿಂಗ-ವರ್ಗೀಕೃತ ವೀರ್ಯಕ್ಕೆ ಸಬ್ಸಿಡಿ.',
    'bn': '🐄 **জাতীয় গোকুল মিশন (RGM)** — দেশি জাত উন্নয়ন, বিনামূল্যে/সস্তায় কৃত্রিম প্রজনন ও সেক্স-সর্টেড বীর্যে ভর্তুকি।',
    'gu': '🐄 **રાષ્ટ્રીય ગોકુલ મિશન (RGM)** — દેશી ઓલાદ સુધારો, મફત/સસ્તું કૃત્રિમ ગર્ભાધાન અને સેક્સ-સોર્ટેડ વીર્ય પર સબસિડી.',
    'pa': '🐄 **ਰਾਸ਼ਟਰੀ ਗੋਕੁਲ ਮਿਸ਼ਨ (RGM)** — ਦੇਸੀ ਨਸਲ ਸੁਧਾਰ, ਮੁਫ਼ਤ/ਸਸਤਾ ਕ੍ਰਿਤ੍ਰਿਮ ਗੱਭਣ ਅਤੇ ਸੈਕਸ-ਸੌਰਟਿਡ ਵੀਰਜ ਤੇ ਸਬਸਿਡੀ।',
    'mr': '🐄 **राष्ट्रीय गोकुळ मिशन (RGM)** — देशी जात सुधारणा, मोफत/स्वस्त कृत्रिम रेतन आणि सेक्स-सॉर्टेड वीर्यावर अनुदान.',
    'bho': '🐄 **राष्ट्रीय गोकुल मिशन (RGM)** — देसी नस्ल सुधार, मुफ्त/सस्ता कृत्रिम गर्भाधान आ सेक्स-सॉर्टेड वीर्य पर अनुदान।',
  },
  '❌ **गलघोंटू (HS) का टीका छोड़ देना** — भैंस में यह बीमारी कुछ घंटों में जान ले लेती है। बरसात से पहले हर साल ज़रूरी।': {
    'ta': '❌ **தொண்டை அடைப்பான் (HS) தடுப்பூசியை விடுவது** — எருமையில் இந்நோய் சில மணிநேரங்களில் உயிரைக் கொல்லும். மழைக்கு முன் ஒவ்வொரு ஆண்டும் அவசியம்.',
    'te': '❌ **గొంతువాపు (HS) టీకా వదిలేయడం** — గేదెలో ఈ వ్యాధి కొన్ని గంటల్లో ప్రాణం తీస్తుంది. వర్షాలకు ముందు ప్రతి సంవత్సరం తప్పనిసరి.',
    'kn': '❌ **ಗಂಟಲು ರೋಗ (HS) ಲಸಿಕೆ ಬಿಡುವುದು** — ಎಮ್ಮೆಯಲ್ಲಿ ಈ ರೋಗ ಕೆಲವು ಗಂಟೆಗಳಲ್ಲಿ ಪ್ರಾಣ ತೆಗೆಯುತ್ತದೆ. ಮಳೆಗೆ ಮುಂಚೆ ಪ್ರತಿ ವರ್ಷ ಅಗತ್ಯ.',
    'bn': '❌ **গলঘোন্টু (HS) এর টিকা বাদ দেওয়া** — মহিষে এই রোগ কয়েক ঘণ্টার মধ্যে প্রাণ কেড়ে নেয়। বর্ষার আগে প্রতি বছর জরুরি।',
    'gu': '❌ **ગલઘોંટૂ (HS) ની રસી છોડી દેવી** — ભેંસમાં આ બીમારી થોડા કલાકમાં જાન લઈ લે છે. વરસાદ પહેલાં દર વર્ષે જરૂરી.',
    'pa': '❌ **ਗਲਘੋਟੂ (HS) ਦਾ ਟੀਕਾ ਛੱਡ ਦੇਣਾ** — ਮੱਝ ਵਿੱਚ ਇਹ ਬੀਮਾਰੀ ਕੁਝ ਘੰਟਿਆਂ ਵਿੱਚ ਜਾਨ ਲੈ ਲੈਂਦੀ ਹੈ। ਬਰਸਾਤ ਤੋਂ ਪਹਿਲਾਂ ਹਰ ਸਾਲ ਜ਼ਰੂਰੀ।',
    'mr': '❌ **घटसर्प (HS) ची लस सोडणे** — म्हशीमध्ये हा आजार काही तासांत जीव घेतो. पावसाळ्यापूर्वी दरवर्षी आवश्यक.',
    'bho': '❌ **गलघोंटू (HS) के टीका छोड़ देल** — भइंस में इ बेमारी कुछ घंटा में जान ले लेवेला। बरसात से पहिले हर साल जरूरी बा।',
  },
  '🏦 **AHIDF (पशुपालन अवसंरचना विकास निधि)** — डेयरी इकाई, दूध प्रसंस्करण और चारा संयंत्र पर 3% ब्याज छूट के साथ कर्ज़।': {
    'ta': '🏦 **AHIDF (கால்நடை அபிவிருத்தி நிதி)** — பால் பண்ணை, பதப்படுத்துதல் மற்றும் தீவன ஆலைக்கு 3% வட்டி தள்ளுபடியுடன் கடன்.',
    'te': '🏦 **AHIDF (పశుసంవర్ధక మౌలిక సదుపాయాల అభివృద్ధి నిధి)** — డైరీ యూనిట్, పాల ప్రాసెసింగ్ మరియు మేత ప్లాంట్‌పై 3% వడ్డీ రాయితీతో రుణం.',
    'kn': '🏦 **AHIDF (ಪಶುಸಂಗೋಪನೆ ಮೂಲಸೌಕರ್ಯ ಅಭಿವೃದ್ಧಿ ನಿಧಿ)** — ಡೇರಿ ಘಟಕ, ಹಾಲು ಸಂಸ್ಕರಣೆ ಮತ್ತು ಮೇವಿನ ಘಟಕಕ್ಕೆ 3% ಬಡ್ಡಿ ರಿಯಾಯಿತಿಯೊಂದಿಗೆ ಸಾಲ.',
    'bn': '🏦 **AHIDF (পশুপালন অবকাঠামো উন্নয়ন তহবিল)** — ডেয়ারি ইউনিট, দুধ প্রক্রিয়াকরণ ও ঘাস প্ল্যান্টে ৩% সুদের ছাড়সহ ঋণ।',
    'gu': '🏦 **AHIDF (પશુપાલન ઇન્ફ્રાસ્ટ્રક્ચર વિકાસ ફંડ)** — ડેરી યુનિટ, દૂધ પ્રોસેસિંગ અને ચારા પ્લાન્ટ પર 3% વ્યાજ રાહત સાથે લોન.',
    'pa': '🏦 **AHIDF (ਪਸ਼ੂ ਪਾਲਣ ਬੁਨਿਆਦੀ ਢਾਂਚਾ ਵਿਕਾਸ ਫੰਡ)** — ਡੇਅਰੀ ਇਕਾਈ, ਦੁੱਧ ਪ੍ਰੋਸੈਸਿੰਗ ਅਤੇ ਚਾਰਾ ਪਲਾਂਟ ਤੇ 3% ਵਿਆਜ ਛੋਟ ਨਾਲ ਕਰਜ਼।',
    'mr': '🏦 **AHIDF (पशुपालन पायाभूत सुविधा विकास निधी)** — डेअरी युनिट, दूध प्रक्रिया आणि चारा प्रकल्पावर 3% व्याज सवलतीसह कर्ज.',
    'bho': '🏦 **AHIDF (पशुपालन अवसंरचना विकास निधि)** — डेयरी इकाई, दूध प्रसंस्करण आ चारा संयंत्र पर 3% ब्याज छूट के साथ कर्ज।',
  },
  'दाना कुल ख़र्च का लगभग 70% है — इसलिए दाने का सही दाम और बर्बादी रोकना ही असली मुनाफ़ा है। शेड का ख़र्च एक बार का है।': {
    'ta': 'தீவனம் மொத்த செலவில் சுமார் 70% ஆகும் — அதனால் தீவனத்தின் சரியான விலையும் வீணாவதைத் தடுப்பதும் தான் உண்மையான லாபம். கொட்டகைச் செலவு ஒருமுறை மட்டுமே.',
    'te': 'దాణా మొత్తం ఖర్చులో సుమారు 70% ఉంటుంది — కాబట్టి దాణా సరైన ధర మరియు వృథా అరికట్టడమే అసలు లాభం. షెడ్ ఖర్చు ఒక్కసారే.',
    'kn': 'ಆಹಾರ ಒಟ್ಟು ಖರ್ಚಿನ ಸುಮಾರು 70% ಆಗಿದೆ — ಆದ್ದರಿಂದ ಆಹಾರದ ಸರಿಯಾದ ಬೆಲೆ ಮತ್ತು ಪೋಲು ತಡೆಯುವುದೇ ನಿಜವಾದ ಲಾಭ. ಶೆಡ್ ಖರ್ಚು ಒಮ್ಮೆ ಮಾತ್ರ.',
    'bn': 'দানা মোট খরচের প্রায় ৭০% — তাই দানার সঠিক দাম ও অপচয় রোধ করাই আসল লাভ। শেডের খরচ এক বারের।',
    'gu': 'દાણ કુલ ખર્ચના લગભગ 70% છે — માટે દાણનો સાચો ભાવ અને બગાડ રોકવો એ જ અસલી નફો છે. શેડનો ખર્ચ એક જ વારનો છે.',
    'pa': 'ਦਾਣਾ ਕੁੱਲ ਖ਼ਰਚ ਦਾ ਲਗਭਗ 70% ਹੈ — ਇਸ ਲਈ ਦਾਣੇ ਦਾ ਸਹੀ ਭਾਅ ਅਤੇ ਬਰਬਾਦੀ ਰੋਕਣਾ ਹੀ ਅਸਲੀ ਮੁਨਾਫ਼ਾ ਹੈ। ਸ਼ੈੱਡ ਦਾ ਖ਼ਰਚ ਇੱਕ ਵਾਰ ਦਾ ਹੈ।',
    'mr': 'खुराक एकूण खर्चाच्या सुमारे 70% असतो — म्हणून खुराकाचा योग्य दर आणि नासाडी थांबवणे हाच खरा नफा आहे. शेडचा खर्च एकाच वेळी असतो.',
    'bho': 'दाना कुल खर्चा के लगभग 70% बा — एही से दाना के सही दाम आ बर्बादी रोकल ही असली मुनाफा बा। शेड के खर्चा एक बेर के होला।',
  },
  '🐔 contract farming पर सोचिए — कंपनी चूज़ा, दाना और दवा देती है और तय दाम पर वापस लेती है। दाम गिरने का ख़तरा नहीं रहता।': {
    'ta': '🐔 contract farming பற்றி யோசியுங்கள் — நிறுவனம் குஞ்சு, தீவனம் மற்றும் மருந்து வழங்கி நிலையான விலைக்குத் திரும்பப் பெறுகிறது. விலை வீழ்ச்சி அபாயம் இல்லை.',
    'te': '🐔 contract farming గురించి ఆలోచించండి — కంపెనీ కోడిపిల్ల, దాణా మరియు మందులు ఇస్తుంది మరియు నిర్ణీత ధరకు తిరిగి తీసుకుంటుంది. ధర తగ్గే ప్రమాదం ఉండదు.',
    'kn': '🐔 contract farming ಬಗ್ಗೆ ಯೋಚಿಸಿ — ಕಂಪನಿ ಮರಿ, ಆಹಾರ ಮತ್ತು ಔಷಧಿ ನೀಡುತ್ತದೆ ಮತ್ತು ನಿಗದಿತ ಬೆಲೆಗೆ ಮರಳಿ ಪಡೆಯುತ್ತದೆ. ಬೆಲೆ ಕುಸಿತದ ಅಪಾಯವಿರುವುದಿಲ್ಲ.',
    'bn': '🐔 contract farming নিয়ে ভাবুন — কোম্পানি ছানা, দানা ও ওষুধ দেয় এবং নির্দিষ্ট দামে ফেরত নেয়। দাম পড়ার ঝুঁকি থাকে না।',
    'gu': '🐔 contract farming પર વિચારો — કંપની બચ્ચાં, દાણ અને દવા આપે છે અને નક્કી ભાવે પાછું લે છે. ભાવ ઘટવાનું જોખમ રહેતું નથી.',
    'pa': '🐔 contract farming ਤੇ ਸੋਚੋ — ਕੰਪਨੀ ਚੂਚਾ, ਦਾਣਾ ਅਤੇ ਦਵਾਈ ਦਿੰਦੀ ਹੈ ਅਤੇ ਤੈਅ ਭਾਅ ਤੇ ਵਾਪਸ ਲੈਂਦੀ ਹੈ। ਭਾਅ ਡਿੱਗਣ ਦਾ ਖ਼ਤਰਾ ਨਹੀਂ ਰਹਿੰਦਾ।',
    'mr': '🐔 contract farming चा विचार करा — कंपनी पिल्लू, खुराक आणि औषध देते आणि ठरलेल्या दराने परत घेते. दर पडण्याचा धोका राहत नाही.',
    'bho': '🐔 contract farming पर सोचीं — कंपनी चूजा, दाना आ दवाई देलीं आ तय दाम पर वापस लेलीं। दाम गिरे के खतरा ना रहेला।',
  },
  '🐝 KVK और राज्य बागवानी विभाग मधुमक्खी बक्से पर अनुदान देते हैं और मुफ़्त प्रशिक्षण भी। पहले प्रशिक्षण लीजिए, फिर बक्से।': {
    'ta': '🐝 KVK மற்றும் மாநில தோட்டக்கலைத் துறை தேனீ பெட்டிகளுக்கு மானியம் மற்றும் இலவச பயிற்சியும் அளிக்கின்றன. முதலில் பயிற்சி பெறுங்கள், பின் பெட்டிகள்.',
    'te': '🐝 KVK మరియు రాష్ట్ర ఉద్యానవన శాఖ తేనెటీగల పెట్టెలపై రాయితీ మరియు ఉచిత శిక్షణ కూడా ఇస్తాయి. ముందు శిక్షణ తీసుకోండి, తర్వాత పెట్టెలు.',
    'kn': '🐝 KVK ಮತ್ತು ರಾಜ್ಯ ತೋಟಗಾರಿಕೆ ಇಲಾಖೆ ಜೇನು ಪೆಟ್ಟಿಗೆಗಳಿಗೆ ಸಬ್ಸಿಡಿ ಮತ್ತು ಉಚಿತ ತರಬೇತಿಯನ್ನೂ ನೀಡುತ್ತವೆ. ಮೊದಲು ತರಬೇತಿ ಪಡೆಯಿರಿ, ನಂತರ ಪೆಟ್ಟಿಗೆ.',
    'bn': '🐝 KVK ও রাজ্য উদ্যানপালন বিভাগ মৌমাছির বাক্সে ভর্তুকি এবং বিনামূল্যে প্রশিক্ষণও দেয়। আগে প্রশিক্ষণ নিন, তারপর বাক্স।',
    'gu': '🐝 KVK અને રાજ્ય બાગાયત વિભાગ મધમાખી બૉક્સ પર સબસિડી આપે છે અને મફત તાલીમ પણ. પહેલાં તાલીમ લો, પછી બૉક્સ.',
    'pa': '🐝 KVK ਅਤੇ ਰਾਜ ਬਾਗਬਾਨੀ ਵਿਭਾਗ ਮਧੂਮੱਖੀ ਡੱਬਿਆਂ ਤੇ ਸਬਸਿਡੀ ਦਿੰਦੇ ਹਨ ਅਤੇ ਮੁਫ਼ਤ ਸਿਖਲਾਈ ਵੀ। ਪਹਿਲਾਂ ਸਿਖਲਾਈ ਲਓ, ਫਿਰ ਡੱਬੇ।',
    'mr': '🐝 KVK आणि राज्य फलोत्पादन विभाग मधमाशी पेट्यांवर अनुदान देतात आणि मोफत प्रशिक्षणही. आधी प्रशिक्षण घ्या, मग पेट्या.',
    'bho': '🐝 KVK आ राज्य बागवानी विभाग मधुमक्खी बक्सा पर अनुदान देलें आ मुफ्त प्रशिक्षण भी। पहिले प्रशिक्षण लीं, फिर बक्सा।',
  },
  '🐄 गाय ख़रीदते समय **दूसरे या तीसरे ब्यांत की** गाय लीजिए — तब वह सबसे ज़्यादा दूध देती है और उसका रिकॉर्ड भी देखा जा सकता है।': {
    'ta': '🐄 பசு வாங்கும்போது **இரண்டாவது அல்லது மூன்றாவது ஈற்று** பசுவை வாங்குங்கள் — அப்போதுதான் அது அதிக பால் தரும், அதன் பதிவையும் பார்க்கலாம்.',
    'te': '🐄 ఆవు కొనేటప్పుడు **రెండవ లేదా మూడవ ఈత** ఆవును తీసుకోండి — అప్పుడే అది అత్యధిక పాలు ఇస్తుంది మరియు దాని రికార్డు కూడా చూడవచ్చు.',
    'kn': '🐄 ಹಸು ಕೊಳ್ಳುವಾಗ **ಎರಡನೇ ಅಥವಾ ಮೂರನೇ ಈತಿನ** ಹಸು ತೆಗೆದುಕೊಳ್ಳಿ — ಆಗ ಅದು ಅತ್ಯಂತ ಹೆಚ್ಚು ಹಾಲು ನೀಡುತ್ತದೆ ಮತ್ತು ಅದರ ದಾಖಲೆಯನ್ನೂ ನೋಡಬಹುದು.',
    'bn': '🐄 গরু কেনার সময় **দ্বিতীয় বা তৃতীয় বারের** গরু নিন — তখন সে সবচেয়ে বেশি দুধ দেয় এবং তার রেকর্ডও দেখা যায়।',
    'gu': '🐄 ગાય ખરીદતી વખતે **બીજા કે ત્રીજા વિયાણની** ગાય લો — ત્યારે તે સૌથી વધુ દૂધ આપે છે અને એનો રેકોર્ડ પણ જોઈ શકાય છે.',
    'pa': '🐄 ਗਾਂ ਖ਼ਰੀਦਣ ਸਮੇਂ **ਦੂਜੇ ਜਾਂ ਤੀਜੇ ਵਿਆਂਤ ਦੀ** ਗਾਂ ਲਓ — ਉਦੋਂ ਉਹ ਸਭ ਤੋਂ ਵੱਧ ਦੁੱਧ ਦਿੰਦੀ ਹੈ ਅਤੇ ਉਸ ਦਾ ਰਿਕਾਰਡ ਵੀ ਦੇਖਿਆ ਜਾ ਸਕਦਾ ਹੈ।',
    'mr': '🐄 गाय खरेदी करताना **दुसऱ्या किंवा तिसऱ्या वेताची** गाय घ्या — तेव्हा ती सर्वाधिक दूध देते आणि तिचा रेकॉर्डही पाहता येतो.',
    'bho': '🐄 गाय खरीदे के समय **दूसरकी या तीसरकी ब्यांत के** गाय लीं — तब उ सबसे जादे दूध देलीं आ ओकर रिकॉर्ड भी देखल जा सकेला।',
  },
  'तालाब/धान के खेत वाले किसान का दाना-ख़र्च आधा रह जाता है, तब मुनाफ़ा और बढ़ता है। बत्तख का अंडा मुर्गी से ₹2-4 महँगा बिकता है।': {
    'ta': 'குளம்/நெல் வயல் உள்ள விவசாயியின் தீவனச் செலவு பாதியாகக் குறையும், அப்போது லாபம் மேலும் கூடும். வாத்து முட்டை கோழி முட்டையை விட ₹2-4 அதிகம் விற்கும்.',
    'te': 'చెరువు/వరి పొలం ఉన్న రైతు దాణా ఖర్చు సగం అవుతుంది, అప్పుడు లాభం మరింత పెరుగుతుంది. బాతు గుడ్డు కోడి గుడ్డు కంటే ₹2-4 ఎక్కువకు అమ్ముడవుతుంది.',
    'kn': 'ಕೊಳ/ಭತ್ತದ ಗದ್ದೆ ಇರುವ ರೈತನ ಆಹಾರ ಖರ್ಚು ಅರ್ಧದಷ್ಟಾಗುತ್ತದೆ, ಆಗ ಲಾಭ ಇನ್ನೂ ಹೆಚ್ಚುತ್ತದೆ. ಬಾತುಕೋಳಿ ಮೊಟ್ಟೆ ಕೋಳಿ ಮೊಟ್ಟೆಗಿಂತ ₹2-4 ದುಬಾರಿಗೆ ಮಾರಾಟವಾಗುತ್ತದೆ.',
    'bn': 'পুকুর/ধানের ক্ষেত থাকা কৃষকের দানার খরচ অর্ধেক থেকে যায়, তখন লাভ আরও বাড়ে। হাঁসের ডিম মুরগির ডিমের চেয়ে ₹২-৪ বেশি দামে বিক্রি হয়।',
    'gu': 'તળાવ/ડાંગરના ખેતરવાળા ખેડૂતનો દાણનો ખર્ચ અડધો રહી જાય છે, ત્યારે નફો વધુ વધે છે. બતકનું ઈંડું મરઘી કરતાં ₹2-4 મોંઘું વેચાય છે.',
    'pa': 'ਤਲਾਬ/ਝੋਨੇ ਦੇ ਖੇਤ ਵਾਲੇ ਕਿਸਾਨ ਦਾ ਦਾਣਾ-ਖ਼ਰਚ ਅੱਧਾ ਰਹਿ ਜਾਂਦਾ ਹੈ, ਉਦੋਂ ਮੁਨਾਫ਼ਾ ਹੋਰ ਵਧਦਾ ਹੈ। ਬੱਤਖ ਦਾ ਆਂਡਾ ਮੁਰਗੀ ਨਾਲੋਂ ₹2-4 ਮਹਿੰਗਾ ਵਿਕਦਾ ਹੈ।',
    'mr': 'तलाव/भाताचे शेत असलेल्या शेतकऱ्याचा खुराकाचा खर्च अर्धा राहतो, तेव्हा नफा आणखी वाढतो. बदकाचे अंडे कोंबडीपेक्षा ₹2-4 महाग विकले जाते.',
    'bho': 'तालाब/धान के खेत वाला किसान के दाना-खर्चा आधा रह जाला, तब मुनाफा औरू बढ़ेला। बत्तख के अंडा मुर्गी से ₹2-4 महँगा बिकेला।',
  },
  '**नहाने या भीगने का इंतज़ाम ज़रूरी** — भैंस को पसीना नहीं आता, इसलिए गर्मी में दिन में 2-3 बार पानी डालिए। यही सबसे बड़ी बात है।': {
    'ta': '**குளிக்கும் அல்லது நனையும் ஏற்பாடு அவசியம்** — எருமைக்கு வேர்க்காது, எனவே வெயிலில் நாளில் 2-3 முறை தண்ணீர் ஊற்றுங்கள். இதுவே முக்கிய விஷயம்.',
    'te': '**స్నానం లేదా తడిసే ఏర్పాటు తప్పనిసరి** — గేదెకు చెమట రాదు, కాబట్టి వేసవిలో రోజుకు 2-3 సార్లు నీళ్ళు పోయండి. ఇదే అత్యంత ప్రధాన విషయం.',
    'kn': '**ಸ್ನಾನ ಅಥವಾ ನೆನೆಯುವ ವ್ಯವಸ್ಥೆ ಅಗತ್ಯ** — ಎಮ್ಮೆಗೆ ಬೆವರು ಬರುವುದಿಲ್ಲ, ಆದ್ದರಿಂದ ಬೇಸಿಗೆಯಲ್ಲಿ ದಿನಕ್ಕೆ 2-3 ಬಾರಿ ನೀರು ಹಾಕಿ. ಇದೇ ಅತ್ಯಂತ ಮುಖ್ಯ ವಿಷಯ.',
    'bn': '**স্নান বা ভেজার ব্যবস্থা জরুরি** — মহিষের ঘাম হয় না, তাই গরমে দিনে 2-3 বার জল ঢালুন। এটাই সবচেয়ে বড় কথা।',
    'gu': '**નહાવાનો કે ભીંજાવાનો ઇંતઝામ જરૂરી** — ભેંસને પરસેવો નથી આવતો, માટે ગરમીમાં દિવસમાં 2-3 વાર પાણી રેડો. આ જ સૌથી મોટી વાત છે.',
    'pa': '**ਨਹਾਉਣ ਜਾਂ ਭਿੱਜਣ ਦਾ ਇੰਤਜ਼ਾਮ ਜ਼ਰੂਰੀ** — ਮੱਝ ਨੂੰ ਪਸੀਨਾ ਨਹੀਂ ਆਉਂਦਾ, ਇਸ ਲਈ ਗਰਮੀ ਵਿੱਚ ਦਿਨ ਵਿੱਚ 2-3 ਵਾਰ ਪਾਣੀ ਪਾਓ। ਇਹੋ ਸਭ ਤੋਂ ਵੱਡੀ ਗੱਲ ਹੈ।',
    'mr': '**आंघोळीची किंवा भिजण्याची व्यवस्था आवश्यक** — म्हशीला घाम येत नाही, म्हणून उन्हाळ्यात दिवसातून 2-3 वेळा पाणी टाका. हीच सर्वात महत्त्वाची गोष्ट आहे.',
    'bho': '**नहाए या भीगे के इंतजाम जरूरी बा** — भइंस के पसीना ना आवेला, एही से गरमी में दिन में 2-3 बेर पानी डालीं। इहे सबसे बड़ बात बा।',
  },
  'खनिज मिश्रण 50 ग्राम रोज़ — यह सबसे सस्ता ख़र्च है और गर्मी में आने (हीट) की सबसे बड़ी वजह। छोड़ा तो गाय समय पर गाभिन नहीं होगी।': {
    'ta': 'தாது கலவை தினமும் 50 கிராம் — இது மிகக் குறைந்த செலவு மற்றும் சினைக்கு வருவதற்கு (ஹீட்) முக்கிய காரணம். விட்டால் பசு நேரத்தில் சினையாகாது.',
    'te': 'ఖనిజ మిశ్రమం రోజూ 50 గ్రాములు — ఇది అత్యంత చౌకైన ఖర్చు మరియు ఎదకు రావడానికి (హీట్) ప్రధాన కారణం. వదిలేస్తే ఆవు సమయానికి గర్భం దాల్చదు.',
    'kn': 'ಖನಿಜ ಮಿಶ್ರಣ ಪ್ರತಿದಿನ 50 ಗ್ರಾಮ್ — ಇದು ಅತ್ಯಂತ ಅಗ್ಗದ ಖರ್ಚು ಮತ್ತು ಕಾವಿಗೆ ಬರಲು (ಹೀಟ್) ಮುಖ್ಯ ಕಾರಣ. ಬಿಟ್ಟರೆ ಹಸು ಸಮಯಕ್ಕೆ ಗರ್ಭಧರಿಸುವುದಿಲ್ಲ.',
    'bn': 'খনিজ মিশ্রণ ৫০ গ্রাম রোজ — এটা সবচেয়ে সস্তা খরচ এবং গরমে আসার (হিট) সবচেয়ে বড় কারণ। ছাড়লে গরু সময়ে গর্ভবতী হবে না।',
    'gu': 'ખનિજ મિશ્રણ 50 ગ્રામ રોજ — આ સૌથી સસ્તો ખર્ચ છે અને ગરમીમાં આવવા (હીટ) નું સૌથી મોટું કારણ. છોડ્યું તો ગાય સમયસર ફેળાશે નહીં.',
    'pa': 'ਖਣਿਜ ਮਿਸ਼ਰਣ 50 ਗ੍ਰਾਮ ਰੋਜ਼ — ਇਹ ਸਭ ਤੋਂ ਸਸਤਾ ਖ਼ਰਚ ਹੈ ਅਤੇ ਗਰਮੀ ਵਿੱਚ ਆਉਣ (ਹੀਟ) ਦੀ ਸਭ ਤੋਂ ਵੱਡੀ ਵਜ੍ਹਾ। ਛੱਡਿਆ ਤਾਂ ਗਾਂ ਸਮੇਂ ਤੇ ਗੱਭਣ ਨਹੀਂ ਹੋਵੇਗੀ।',
    'mr': 'खनिज मिश्रण 50 ग्रॅम रोज — हा सर्वात स्वस्त खर्च आहे आणि माजावर येण्याचे (हीट) सर्वात मोठे कारण. सोडल्यास गाय वेळेवर गाभण होणार नाही.',
    'bho': 'खनिज मिश्रण 50 ग्राम रोज — इ सबसे सस्ता खर्चा बा आ गरमी में आवे (हीट) के सबसे बड़ वजह। छोड़नी त गाय समय पर गाभिन ना होई।',
  },
  '📌 दाना का सीधा हिसाब: **1.5 किग्रा (रखरखाव) + हर लीटर दूध पर 400 ग्राम**। 10 लीटर देने वाली गाय = 1.5 + 4 = साढ़े 5 किग्रा दाना।': {
    'ta': '📌 தீவன நேரடி கணக்கு: **1.5 கிலோ (பராமரிப்பு) + ஒவ்வொரு லிட்டர் பாலுக்கும் 400 கிராம்**. 10 லிட்டர் தரும் பசு = 1.5 + 4 = சாடே 5 கிலோ தீவனம்.',
    'te': '📌 దాణా నేరుగా లెక్క: **1.5 కిలోలు (నిర్వహణ) + ప్రతి లీటరు పాలపై 400 గ్రాములు**. 10 లీటర్లు ఇచ్చే ఆవు = 1.5 + 4 = సాడే 5 కిలోల దాణా.',
    'kn': '📌 ಆಹಾರದ ನೇರ ಲೆಕ್ಕ: **1.5 ಕಿಲೋ (ನಿರ್ವಹಣೆ) + ಪ್ರತಿ ಲೀಟರ್ ಹಾಲಿಗೆ 400 ಗ್ರಾಮ್**. 10 ಲೀಟರ್ ನೀಡುವ ಹಸು = 1.5 + 4 = ಸಾಡೇ 5 ಕಿಲೋ ಆಹಾರ.',
    'bn': '📌 দানার সোজা হিসাব: **1.5 কিলো (রক্ষণাবেক্ষণ) + প্রতি লিটার দুধে 400 গ্রাম**। 10 লিটার দেওয়া গরু = 1.5 + 4 = সাড়ে 5 কিলো দানা।',
    'gu': '📌 દાણનો સીધો હિસાબ: **1.5 કિલો (નિભાવ) + દર લિટર દૂધ પર 400 ગ્રામ**. 10 લિટર આપતી ગાય = 1.5 + 4 = સાડા 5 કિલો દાણ.',
    'pa': '📌 ਦਾਣੇ ਦਾ ਸਿੱਧਾ ਹਿਸਾਬ: **1.5 ਕਿਲੋ (ਦੇਖਭਾਲ) + ਹਰ ਲੀਟਰ ਦੁੱਧ ਤੇ 400 ਗ੍ਰਾਮ**। 10 ਲੀਟਰ ਦਿੰਦੀ ਗਾਂ = 1.5 + 4 = ਸਾਢੇ 5 ਕਿਲੋ ਦਾਣਾ।',
    'mr': '📌 खुराकाचे थेट गणित: **1.5 किलो (निगा) + दर लिटर दुधावर 400 ग्रॅम**. 10 लिटर देणारी गाय = 1.5 + 4 = साडे 5 किलो खुराक.',
    'bho': '📌 दाना के सीधा हिसाब: **1.5 किलो (रखरखाव) + हर लीटर दूध पर 400 ग्राम**। 10 लीटर देवे वाली गाय = 1.5 + 4 = साढ़े 5 किलो दाना।',
  },
  'माँग अभी शहरों और क्रिसमस के आसपास ही ज़्यादा है — पहले ख़रीदार पक्का करें। मुर्गी के साथ कभी न पालें (ब्लैकहेड बीमारी का ख़तरा)।': {
    'ta': 'தேவை தற்போது நகரங்கள் மற்றும் கிறிஸ்மஸ் சமயத்தில் தான் அதிகம் — முதலில் வாங்குபவரை உறுதி செய்யுங்கள். கோழியுடன் வளர்க்காதீர்கள் (பிளாக்ஹெட் நோய் ஆபத்து).',
    'te': 'డిమాండ్ ప్రస్తుతం నగరాలు మరియు క్రిస్మస్ సమయంలోనే ఎక్కువ — ముందు కొనుగోలుదారుని నిశ్చయించండి. కోడితో ఎప్పుడూ పెంచకండి (బ్లాక్‌హెడ్ వ్యాధి ప్రమాదం).',
    'kn': 'ಬೇಡಿಕೆ ಈಗ ನಗರಗಳು ಮತ್ತು ಕ್ರಿಸ್‌ಮಸ್ ಸಮಯದಲ್ಲಿ ಹೆಚ್ಚು — ಮೊದಲು ಖರೀದಿದಾರರನ್ನು ಖಚಿತಪಡಿಸಿ. ಕೋಳಿಯೊಂದಿಗೆ ಎಂದಿಗೂ ಸಾಕಬೇಡಿ (ಬ್ಲ್ಯಾಕ್‌ಹೆಡ್ ರೋಗದ ಅಪಾಯ).',
    'bn': 'চাহিদা এখন শহর ও বড়দিনের আশেপাশেই বেশি — আগে ক্রেতা নিশ্চিত করুন। মুরগির সাথে কখনো পালবেন না (ব্ল্যাকহেড রোগের ঝুঁকি)।',
    'gu': 'માગ અત્યારે શહેરો અને ક્રિસમસ આસપાસ જ વધુ છે — પહેલાં ખરીદનાર પાક્કો કરો. મરઘી સાથે ક્યારેય ન પાળો (બ્લેકહેડ બીમારીનું જોખમ).',
    'pa': 'ਮੰਗ ਹੁਣੇ ਸ਼ਹਿਰਾਂ ਅਤੇ ਕ੍ਰਿਸਮਸ ਦੇ ਆਸ-ਪਾਸ ਹੀ ਵੱਧ ਹੈ — ਪਹਿਲਾਂ ਖ਼ਰੀਦਦਾਰ ਪੱਕਾ ਕਰੋ। ਮੁਰਗੀ ਨਾਲ ਕਦੇ ਨਾ ਪਾਲੋ (ਬਲੈਕਹੈੱਡ ਬੀਮਾਰੀ ਦਾ ਖ਼ਤਰਾ)।',
    'mr': 'मागणी सध्या शहरांमध्ये आणि ख्रिसमसच्या सुमारास जास्त आहे — आधी खरेदीदार निश्चित करा. कोंबडीसोबत कधीही पाळू नका (ब्लॅकहेड आजाराचा धोका).',
    'bho': 'माँग अभी शहर आ क्रिसमस के आसपास ही जादे बा — पहिले खरीदार पक्का करीं। मुर्गी के साथ कबो ना पालबें (ब्लैकहेड बेमारी के खतरा)।',
  },
  'सब बच्चे एक साथ नहीं बिकते — कुछ को बड़ा करके बेचना ज़्यादा फ़ायदेमंद रहता है। बचा हुआ भोजन मिल जाए तो दाना-ख़र्च आधा हो जाता है।': {
    'ta': 'எல்லா குட்டிகளும் ஒரே நேரத்தில் விற்பதில்லை — சிலவற்றை வளர்த்து விற்பது அதிக லாபகரம். மீதி உணவு கிடைத்தால் தீவனச் செலவு பாதியாகும்.',
    'te': 'అన్ని పిల్లలు ఒకేసారి అమ్ముడుపోవు — కొన్నింటిని పెద్దవి చేసి అమ్మడం లాభదాయకం. మిగిలిన ఆహారం దొరికితే దాణా ఖర్చు సగం అవుతుంది.',
    'kn': 'ಎಲ್ಲ ಮರಿಗಳು ಒಂದೇ ಬಾರಿಗೆ ಮಾರಾಟವಾಗುವುದಿಲ್ಲ — ಕೆಲವನ್ನು ದೊಡ್ಡದು ಮಾಡಿ ಮಾರುವುದು ಹೆಚ್ಚು ಲಾಭದಾಯಕ. ಮಿಕ್ಕಿದ ಊಟ ಸಿಕ್ಕರೆ ಆಹಾರ ಖರ್ಚು ಅರ್ಧವಾಗುತ್ತದೆ.',
    'bn': 'সব বাচ্চা একসাথে বিক্রি হয় না — কিছুকে বড় করে বেচা বেশি লাভজনক। বেঁচে যাওয়া খাবার মিললে দানার খরচ অর্ধেক হয়ে যায়।',
    'gu': 'બધાં બચ્ચાં એક સાથે નથી વેચાતાં — કેટલાંકને મોટાં કરીને વેચવાં વધુ ફાયદાકારક રહે છે. વધેલું ભોજન મળે તો દાણનો ખર્ચ અડધો થઈ જાય છે.',
    'pa': 'ਸਭ ਬੱਚੇ ਇੱਕੋ ਵਾਰ ਨਹੀਂ ਵਿਕਦੇ — ਕੁਝ ਨੂੰ ਵੱਡਾ ਕਰਕੇ ਵੇਚਣਾ ਵੱਧ ਲਾਹੇਵੰਦ ਰਹਿੰਦਾ ਹੈ। ਬਚਿਆ ਭੋਜਨ ਮਿਲ ਜਾਵੇ ਤਾਂ ਦਾਣਾ-ਖ਼ਰਚ ਅੱਧਾ ਹੋ ਜਾਂਦਾ ਹੈ।',
    'mr': 'सर्व पिल्ले एकाच वेळी विकली जात नाहीत — काहींना मोठे करून विकणे जास्त फायदेशीर ठरते. उरलेले अन्न मिळाल्यास खुराकाचा खर्च अर्धा होतो.',
    'bho': 'सब बच्चा एकसाथ ना बिकेला — कुछ के बड़ करके बेचल जादे फायदेमंद रहेला। बचल भोजन मिल जाई त दाना-खर्चा आधा हो जाला।',
  },
  'पहले साल शेड का ख़र्च एक ही बार लगता है, इसलिए दूसरे साल से मुनाफ़ा लगभग दुगना दिखता है। दाम इलाक़े और त्योहार पर निर्भर करते हैं।': {
    'ta': 'முதல் ஆண்டில் கொட்டகைச் செலவு ஒருமுறை மட்டுமே, எனவே இரண்டாம் ஆண்டிலிருந்து லாபம் இருமடங்காகத் தெரியும். விலை பகுதி மற்றும் பண்டிகையைப் பொறுத்தது.',
    'te': 'మొదటి సంవత్సరం షెడ్ ఖర్చు ఒక్కసారే ఉంటుంది, కాబట్టి రెండవ సంవత్సరం నుండి లాభం రెట్టింపుగా కనిపిస్తుంది. ధరలు ప్రాంతం మరియు పండుగలపై ఆధారపడతాయి.',
    'kn': 'ಮೊದಲ ವರ್ಷ ಶೆಡ್ ಖರ್ಚು ಒಮ್ಮೆ ಮಾತ್ರ, ಆದ್ದರಿಂದ ಎರಡನೇ ವರ್ಷದಿಂದ ಲಾಭ ದ್ವಿಗುಣವಾಗಿ ಕಾಣಿಸುತ್ತದೆ. ಬೆಲೆಗಳು ಪ್ರದೇಶ ಮತ್ತು ಹಬ್ಬವನ್ನು ಅವಲಂಬಿಸಿವೆ.',
    'bn': 'প্রথম বছর শেডের খরচ এক বারই লাগে, তাই দ্বিতীয় বছর থেকে লাভ প্রায় দ্বিগুণ দেখায়। দাম এলাকা ও উৎসবের উপর নির্ভর করে।',
    'gu': 'પહેલા વર્ષે શેડનો ખર્ચ એક જ વાર લાગે છે, માટે બીજા વર્ષથી નફો લગભગ બમણો દેખાય છે. ભાવ વિસ્તાર અને તહેવાર પર આધાર રાખે છે.',
    'pa': 'ਪਹਿਲੇ ਸਾਲ ਸ਼ੈੱਡ ਦਾ ਖ਼ਰਚ ਇੱਕੋ ਵਾਰ ਲੱਗਦਾ ਹੈ, ਇਸ ਲਈ ਦੂਜੇ ਸਾਲ ਤੋਂ ਮੁਨਾਫ਼ਾ ਲਗਭਗ ਦੁਗਣਾ ਦਿਸਦਾ ਹੈ। ਭਾਅ ਇਲਾਕੇ ਅਤੇ ਤਿਉਹਾਰ ਤੇ ਨਿਰਭਰ ਕਰਦੇ ਹਨ।',
    'mr': 'पहिल्या वर्षी शेडचा खर्च एकाच वेळी असतो, म्हणून दुसऱ्या वर्षापासून नफा जवळपास दुप्पट दिसतो. दर भाग आणि सणांवर अवलंबून असतात.',
    'bho': 'पहिला साल शेड के खर्चा एक बेर ही लागेला, एही से दूसरका साल से मुनाफा लगभग दुगना दिखेला। दाम इलाका आ त्योहार पर निर्भर करेला।',
  },
  'जहाँ मुफ़्त चराई मिलती है वहाँ लागत आधी रह जाती है — यही भेड़ पालन की असली ताक़त है। बकरे की तुलना में भेड़ का दाम थोड़ा कम रहता है।': {
    'ta': 'இலவச மேய்ச்சல் உள்ள இடங்களில் அடக்கவிலை பாதியாகும் — இதுவே செம்மறி ஆடு வளர்ப்பின் பலம். வெள்ளாட்டை விட செம்மறி விலை சற்று குறைவு.',
    'te': 'ఉచిత మేత దొరికే చోట వ్యయం సగం అవుతుంది — ఇదే గొర్రెల పెంపకం అసలు బలం. మేకతో పోలిస్తే గొర్రె ధర కొద్దిగా తక్కువ ఉంటుంది.',
    'kn': 'ಉಚಿತ ಮೇಯುವಿಕೆ ಸಿಗುವಲ್ಲಿ ವೆಚ್ಚ ಅರ್ಧವಾಗುತ್ತದೆ — ಇದೇ ಕುರಿ ಸಾಕಣೆಯ ನಿಜವಾದ ಶಕ್ತಿ. ಹೋತನಿಗೆ ಹೋಲಿಸಿದರೆ ಕುರಿ ಬೆಲೆ ಸ್ವಲ್ಪ ಕಡಿಮೆ ಇರುತ್ತದೆ.',
    'bn': 'যেখানে বিনামূল্যে চারণ মেলে সেখানে খরচ অর্ধেক থেকে যায় — এটাই ভেড়া পালনের আসল শক্তি। পাঁঠার তুলনায় ভেড়ার দাম কিছুটা কম থাকে।',
    'gu': 'જ્યાં મફત ચરાણ મળે છે ત્યાં પડતર અડધી રહી જાય છે — આ જ ઘેટાં પાલનની અસલી તાકાત છે. બકરાની સરખામણીએ ઘેટાંનો ભાવ થોડો ઓછો રહે છે.',
    'pa': 'ਜਿੱਥੇ ਮੁਫ਼ਤ ਚਰਾਈ ਮਿਲਦੀ ਹੈ ਉੱਥੇ ਲਾਗਤ ਅੱਧੀ ਰਹਿ ਜਾਂਦੀ ਹੈ — ਇਹੋ ਭੇਡ ਪਾਲਣ ਦੀ ਅਸਲੀ ਤਾਕਤ ਹੈ। ਬੱਕਰੇ ਦੀ ਤੁਲਨਾ ਵਿੱਚ ਭੇਡ ਦਾ ਭਾਅ ٿੋੜ੍ਹਾ ਘੱਟ ਰਹਿੰਦਾ ਹੈ।',
    'mr': 'जिथे मोफत चराई मिळते तिथे खर्च अर्धा राहतो — हीच मेंढी पालनाची खरी ताकद आहे. बोकडाच्या तुलनेत मेंढीचा दर थोडा कमी असतो.',
    'bho': 'जहाँ मुफ्त चराई मिलेला वहाँ लागत आधा रह जाला — इहे भेड़ पालन के असली ताकत बा। बकरा के तुलना में भेड़ के दाम थोड़ा कम रहेला।',
  },
  '🥛 **डेयरी सहकारी समिति की सदस्यता** — रोज़ का पक्का भुगतान, पशु आहार सस्ते दाम पर, और मुफ़्त पशु चिकित्सा सेवा। सबसे पहले यही कीजिए।': {
    'ta': '🥛 **பால் கூட்டுறவு சங்க உறுப்பினர் தகுதி** — தினசரி உறுதி பணம், குறைந்த விலையில் கால்நடைத் தீவனம், மற்றும் இலவச மருத்துவ சேவை. இதை முதலில் செய்யுங்கள்.',
    'te': '🥛 **డైరీ సహకార సంఘం సభ్యత్వం** — రోజూ పక్కా చెల్లింపు, చౌకగా పశువుల మేత, మరియు ఉచిత పశువైద్య సేవ. ముందస్తుగా ఇదే చేయండి.',
    'kn': '🥛 **ಡೇರಿ ಸಹಕಾರ ಸಂಘದ ಸದಸ್ಯತ್ವ** — ಪ್ರತಿದಿನ ಖಚಿತ ಪಾವತಿ, ಅಗ್ಗದ ಬೆಲೆಯಲ್ಲಿ ಪಶು ಆಹಾರ, ಮತ್ತು ಉಚಿತ ಪಶು ವೈದ್ಯಕೀಯ ಸೇವೆ. ಮೊದಲು ಇದನ್ನು ಮಾಡಿ.',
    'bn': '🥛 **ডেয়ারি সমবায় সমিতির সদস্যপদ** — রোজের নিশ্চিত পেমেন্ট, সস্তায় পশু খাদ্য, এবং বিনামূল্যে পশু চিকিৎসা সেবা। সবথেকে আগে এটাই করুন।',
    'gu': '🥛 **ડેરી સહકારી મંડળીની સભ્યપદ** — રોજનું પાકું ચુકવણું, સસ્તા ભાવે પશુ આહાર, અને મફત પશુ ચિકિત્સા સેવા. સૌથી પહેલાં આ જ કરો.',
    'pa': '🥛 **ਡੇਅਰੀ ਸਹਿਕਾਰੀ ਸਭਾ ਦੀ ਮੈਂਬਰੀ** — ਰੋਜ਼ ਦੀ ਪੱਕੀ ਅਦਾਇਗੀ, ਪਸ਼ੂ ਖ਼ੁਰਾਕ ਸਸਤੇ ਭਾਅ ਤੇ, ਅਤੇ ਮੁਫ਼ਤ ਪਸ਼ੂ ਚਿਕਿਤਸਾ ਸੇਵਾ। ਸਭ ਤੋਂ ਪਹਿਲਾਂ ਇਹੋ ਕਰੋ।',
    'mr': '🥛 **डेअरी सहकारी संस्थेचे सदस्यत्व** — रोजचे पक्के पेमेंट, स्वस्त दरात पशुखाद्य, आणि मोफत पशुवैद्यकीय सेवा. सर्वात आधी हेच करा.',
    'bho': '🥛 **डेयरी सहकारी समिति के सदस्यता** — रोज के पक्का भुगतान, पशु आहार सस्ता दाम पर, आ मुफ्त पशु चिकित्सा सेवा। सबसे पहिले इहे करीं।',
  },
  '❌ **बकरी को 6-8 माह में ही गाभिन करा देना** — शरीर बना नहीं होता, बच्चा कमज़ोर और बकरी ख़राब। 10-12 माह या 25 किग्रा से पहले कभी नहीं।': {
    'ta': '❌ **வெள்ளாட்டை 6-8 மாதத்தில் சினையாக்குவது** — உடல் வளர்ச்சி இராது, குட்டி பலவீனம் மற்றும் ஆடும் வீணாகும். 10-12 மாதம் அல்லது 25 கிலோ முன் வேண்டாம்.',
    'te': '❌ **మేకను 6-8 నెలల్లోనే కలపడం** — శరీరం తయారవ్వదు, పిల్ల బలహీనం మరియు మేక పాడవుతుంది. 10-12 నెలలు లేదా 25 కిలోలకు ముందెన్నడూ వద్దు.',
    'kn': '❌ **ಆಡನ್ನು 6-8 ತಿಂಗಳಿನಲ್ಲೇ ಗರ್ಭಧರಿಸುವಂತೆ ಮಾಡುವುದು** — ಶರೀರ ಬೆಳೆದಿರುವುದಿಲ್ಲ, ಮರಿ ದುರ್ಬಲ ಮತ್ತು ಆಡು ಹಾಳು. 10-12 ತಿಂಗಳು ಅಥವಾ 25 ಕಿಲೋ ಮುಂಚೆ ಎಂದಿಗೂ ಬೇಡ.',
    'bn': '❌ **ছাগলকে 6-8 মাসেই গর্ভবতী করানো** — শরীর তৈরি হয় না, বাচ্চা দুর্বল ও ছাগল নষ্ট। 10-12 মাস বা 25 কিলোর আগে কখনো নয়।',
    'gu': '❌ **બકરીને 6-8 મહિનામાં જ ફેળવી દેવી** — શરીર બનેલું હોતું નથી, બચ્ચું નબળું અને બકરી ખરાબ. 10-12 મહિના કે 25 કિલો પહેલાં ક્યારેય નહીં.',
    'pa': '❌ **ਬੱਕਰੀ ਨੂੰ 6-8 ਮਹੀਨੇ ਵਿੱਚ ਹੀ ਗੱਭਣ ਕਰਵਾ ਦੇਣਾ** — ਸਰੀਰ ਬਣਿਆ ਨਹੀਂ ਹੁੰਦਾ, ਬੱਚਾ ਕਮਜ਼ੋਰ ਅਤੇ ਬੱਕਰੀ ਖ਼ਰਾਬ। 10-12 ਮਹੀਨੇ ਜਾਂ 25 ਕਿਲੋ ਤੋਂ ਪਹਿਲਾਂ ਕਦੇ ਨਹੀਂ।',
    'mr': '❌ **शेळीला 6-8 महिन्यांतच गाभण करणे** — शरीर तयार झालेले नसते, पिल्लू कमकुवत आणि शेळी खराब. 10-12 महिने किंवा 25 किलो आधी कधीही नको.',
    'bho': '❌ **बकरी के 6-8 महीना में ही गाभिन करा देल** — शरीर बनल ना रहेला, बच्चा कमजोर आ बकरी खराब। 10-12 महीना या 25 किलो से पहिले कबो ना।',
  },
  'एक चक्र सिर्फ़ 5 हफ़्ते का — साल में 8-9 चक्र संभव। अंडे वाली बटेर रखें तो 1,000 बटेर से रोज़ ~700 अंडे (₹2-3 प्रति अंडा) की अलग आमदनी।': {
    'ta': 'ஒரு சுழற்சி 5 வாரங்கள் மட்டுமே — ஆண்டில் 8-9 சுழற்சிகள் சாத்தியம். முட்டை காடை வளர்த்தால் 1,000 காடையிலிருந்து தினமும் ~700 முட்டைகள் (முட்டைக்கு ₹2-3) தனி வருமானம்.',
    'te': 'ఒక చక్రం 5 వారాలే — సంవత్సరంలో 8-9 చక్రాలు సాధ్యం. గుడ్ల బటేర్ పెడితే 1,000 బటేర్ల నుండి రోజూ ~700 గుడ్లు (గుడ్డుకు ₹2-3) ప్రత్యేక ఆదాయం.',
    'kn': 'ಒಂದು ಚಕ್ರ ಕೇವಲ 5 ವಾರದ್ದು — ವರ್ಷದಲ್ಲಿ 8-9 ಚಕ್ರ ಸಾಧ್ಯ. ಮೊಟ್ಟೆ ಇಡುವ ಕಾಡೆ ಇಟ್ಟರೆ 1,000 ಕಾಡೆಯಿಂದ ದಿನಕ್ಕೆ ~700 ಮೊಟ್ಟೆ (ಮೊಟ್ಟೆಗೆ ₹2-3) ಪ್ರತ್ಯೇಕ ಆದಾಯ.',
    'bn': 'একটি চক্র মাত্র ৫ সপ্তাহের — বছরে ৮-৯ টি চক্র সম্ভব। ডিমের কোয়েল রাখলে ১,০০০ কোয়েল থেকে রোজ ~৭০০ ডিম (প্রতি ডিম ₹২-৩) আলাদা আয়।',
    'gu': 'એક ચક્ર માત્ર 5 અઠવાડિયાનું — વર્ષમાં 8-9 ચક્ર શક્ય. ઈંડાંવાળી બટેર રાખો તો 1,000 બટેરથી રોજ ~700 ઈંડાં (ઈંડે ₹2-3) ની અલગ આવક.',
    'pa': 'ਇੱਕ ਚੱਕਰ ਸਿਰਫ਼ 5 ਹਫ਼ਤਿਆਂ ਦਾ — ਸਾਲ ਵਿੱਚ 8-9 ਚੱਕਰ ਸੰਭਵ। ਆਂਡਿਆਂ ਵਾਲੀ ਬਟੇਰ ਰੱਖੋ ਤਾਂ 1,000 ਬਟੇਰ ਤੋਂ ਰੋਜ਼ ~700 ਆਂਡੇ (₹2-3 ਪ੍ਰਤੀ ਆਂਡਾ) ਦੀ ਵੱਖਰੀ ਆਮਦਨ।',
    'mr': 'एक चक्र फक्त 5 आठवड्यांचे — वर्षात 8-9 चक्रे शक्य. अंड्यांची लावा (बटेर) ठेवल्यास 1,000 लावा पक्षांपासून रोज ~700 अंडी (₹2-3 प्रति अंडे) वेगळे उत्पन्न.',
    'bho': 'एगो चक्र सिर्फ 5 हफ्ता के — साल में 8-9 चक्र संभव। अंडा वाली बटेर राखब त 1,000 बटेर से रोज ~700 अंडा (₹2-3 प्रति अंडा) के अलगा आमदनी।',
  },
  'खरगोश के मांस का बाज़ार अभी सीमित है — शुरू करने से पहले ख़रीदार पक्का करें। पालतू (pet) और अंगोरा ऊन वाले रास्ते ज़्यादा भरोसेमंद हैं।': {
    'ta': 'முயல் இறைச்சி சந்தை தற்போது எல்லைக்குட்பட்டது — தொடங்குமுன் வாங்குபவரை உறுதி செய்யுங்கள். செல்லப்பிராணி (pet) மற்றும் அங்கோரா கம்பளி பாதைகள் நம்பிக்கையானவை.',
    'te': 'కుందేలు మాంసం మార్కెట్ ప్రస్తుతం పరిమితం — ప్రారంభించే ముందు కొనుగోలుదారుని నిశ్చయించండి. పెంపుడు (pet) మరియు అంగోరా ఉన్ని మార్గాలు నమ్మదగినవి.',
    'kn': 'ಮೊಲದ ಮಾಂಸದ ಮಾರುಕಟ್ಟೆ ಈಗ ಸೀಮಿತವಾಗಿದೆ — ಶುರು ಮಾಡುವ ಮುನ್ನ ಖರೀದಿದಾರರನ್ನು ಖಚಿತಪಡಿಸಿ. ಸಾಕು (pet) ಮತ್ತು ಅಂಗೋರಾ ಉಣ್ಣೆಯ ಮಾರ್ಗಗಳು ಹೆಚ್ಚು ನಂಬಿಗಸ್ತ.',
    'bn': 'খরগোশের মাংসের বাজার এখনো সীমিত — শুরু করার আগে ক্রেতা নিশ্চিত করুন। পোষা (pet) ও অঙ্গোরা পশমের পথ বেশি নির্ভরযোগ্য।',
    'gu': 'સસલાના માંસનું બજાર અત્યારે સીમિત છે — શરૂ કરતાં પહેલાં ખરીદનાર પાક્કો કરો. પાલતુ (pet) અને અંગોરા ઊનવાળા રસ્તા વધુ ભરોસાપાત્ર છે.',
    'pa': 'ਖ਼ਰਗੋਸ਼ ਦੇ ਮੀਟ ਦਾ ਬਾਜ਼ਾਰ ਹੁਣੇ ਸੀਮਤ ਹੈ — ਸ਼ੁਰੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਖ਼ਰੀਦਦਾਰ ਪੱਕਾ ਕਰੋ। ਪਾਲਤੂ (pet) ਅਤੇ ਅੰਗੋਰਾ ਉੱਨ ਵਾਲੇ ਰਾਹ ਜ਼ਿਆਦਾ ਭਰੋਸੇਯੋਗ ਹਨ।',
    'mr': 'सशाच्या मांसाची बाजारपेठ सध्या मर्यादित आहे — सुरू करण्यापूर्वी खरेदीदार निश्चित करा. पाळीव (pet) आणि अंगोरा लोकरीचे मार्ग जास्त विश्वासार्ह आहेत.',
    'bho': 'खरगोश के मांस के बजार अभी सीमित बा — शुरू करे से पहिले खरीदार पक्का करीं। पालतू (pet) आ अंगोरा ऊन वाला रस्ता जादे भरोसेमंद बा।',
  },
  'दुग्ध ज्वर (मिल्क फ़ीवर) — ब्याने के तुरंत बाद गाय बैठ जाती है, उठ नहीं पाती। कैल्शियम की कमी। तुरंत डॉक्टर बुलाइए, देर की तो जान जाती है।': {
    'ta': 'பால் ஜுரம் (மில்க் ஃபீவர்) — ஈன்ற உடனே பசு படுத்துவிடும், எழ முடியாது. கால்சியம் குறைபாடு. உடனே டாக்டர் அழையுங்கள், தாமதித்தால் உயிரிழப்பு.',
    'te': 'పాల జ్వరం (మిల్క్ ఫీవర్) — ఈనిన వెంటనే ఆవు కూర్చుండిపోతుంది, లేవలేదు. కాల్షియం లోపం. వెంటనే డాక్టర్‌ను పిలవండి, ఆలస్యమైతే ప్రాణం పోతుంది.',
    'kn': 'ಹಾಲು ಜ್ವರ (ಮಿಲ್ಕ್ ಫೀವರ್) — ಈಯ್ದ ತಕ್ಷಣ ಹಸು ಕುಳಿತುಬಿಡುತ್ತದೆ, ಏಳಲಾಗುವುದಿಲ್ಲ. ಕ್ಯಾಲ್ಸಿಯಂ ಕೊರತೆ. ತಕ್ಷಣ ವೈದ್ಯರನ್ನು ಕರೆಯಿರಿ, ತಡವಾದರೆ ಪ್ರಾಣ ಹೋಗುತ್ತದೆ.',
    'bn': 'দুগ্ধ জ্বর (মিল্ক ফিভার) — বাচ্চা দেওয়ার পরপরই গরু বসে পড়ে, উঠতে পারে না। ক্যালসিয়ামের অভাব। তৎক্ষণাৎ ডাক্তার ডাকুন, দেরি হলে প্রাণ যায়।',
    'gu': 'દૂધ તાવ (મિલ્ક ફીવર) — વિયાણાના તરત પછી ગાય બેસી જાય છે, ઊભી થઈ શકતી નથી. કૅલ્શિયમની ખામી. તરત ડૉક્ટર બોલાવો, વાર કરી તો જાન જાય છે.',
    'pa': 'ਦੁੱਧ ਬੁਖ਼ਾਰ (ਮਿਲਕ ਫ਼ੀਵਰ) — ਵਿਆਉਣ ਤੋਂ ਤੁਰੰਤ ਬਾਅਦ ਗਾਂ ਬੈਠ ਜਾਂਦੀ ਹੈ, ਉੱਠ ਨਹੀਂ ਸਕਦੀ। ਕੈਲਸ਼ੀਅਮ ਦੀ ਕਮੀ। ਤੁਰੰਤ ਡਾਕਟਰ ਬੁਲਾਓ, ਦੇਰੀ ਕੀਤੀ ਤਾਂ ਜਾਨ ਜਾਂਦੀ ਹੈ।',
    'mr': 'दुग्ध ज्वर (मिल्क फीवर) — व्यायानंतर लगेचच गाय बसते, उठू शकत नाही. कॅल्शियमची कमतरता. तातडीने डॉक्टर बोलवा, उशीर केल्यास जीव जातो.',
    'bho': 'दुग्ध ज्वर (मिल्क फीवर) — बियाए के तुरंत बाद गाय बइठ जालीं, उठ ना पावेलीं। कैल्शियम के कमी। तुरंत डॉक्टर बोलाईं, देर भइल त जान जाला।',
  },
  '❌ **"वापस ख़रीद लेंगे" के वादे पर महँगे चूज़े लेना** — एमू में यही सबसे बड़ी ठगी हुई है। लिखित समझौते और अपने बाज़ार के बिना मत शुरू कीजिए।': {
    'ta': '❌ **"திரும்ப வாங்குவோம்" என்ற வாக்குறுதியில் дорого குஞ்சுகள் வாங்குவது** — ஈமுவில் இதுவே பெரிய ஏமாற்று. எழுத்துப்பூர்வ ஒப்பந்தம் மற்றும் சொந்த சந்தை இன்றி தொடங்காதீர்கள்.',
    'te': '❌ **"తిరిగి కొంటాము" అనే హామీతో ఖరీదైన కోడిపిల్లలు తీసుకోవడం** — ఈమూలో ఇదే అతిపెద్ద మోసం. రాతపూర్వక ఒప్పందం మరియు సొంత మార్కెట్ లేకుండా ప్రారంభించకండి.',
    'kn': '❌ **"ಮರಳಿ ಕೊಳ್ಳುತ್ತೇವೆ" ಎಂಬ ಭರವಸೆಗೆ ದುಬಾರಿ ಮರಿಗಳನ್ನು ಪಡೆಯುವುದು** — ಈಮುನಲ್ಲಿ ಇದೇ ಅತಿ ದೊಡ್ಡ ವಂಚನೆ. ಲಿಖಿತ ಒಪ್ಪಂದ ಮತ್ತು ಸ್ವಂತ ಮಾರುಕಟ್ಟೆಯಿಲ್ಲದೆ ಶುರು ಮಾಡಬೇಡಿ.',
    'bn': '❌ **"ফেরত কিনব" এর প্রতিশ্রুতিতে দামি ছানা নেওয়া** — এমুতে এটাই সবচেয়ে বড় প্রতারণা হয়েছে। লিখিত চুক্তি ও নিজের বাজার ছাড়া শুরু করবেন না।',
    'gu': '❌ **"પાછા ખરીદી લઈશું" ના વાયદા પર મોંઘા બચ્ચાં લેવાં** — ઈમુમાં આ જ સૌથી મોટી ઠગાઈ થઈ છે. લેખિત કરાર અને પોતાના બજાર વિના શરૂ ન કરો.',
    'pa': '❌ **"ਵਾਪਸ ਖ਼ਰੀਦ ਲਵਾਂਗੇ" ਦੇ ਵਾਅਦੇ ਤੇ ਮਹਿੰਗੇ ਚੂਚੇ ਲੈਣਾ** — ਈਮੂ ਵਿੱਚ ਇਹੋ ਸਭ ਤੋਂ ਵੱਡੀ ਠੱਗੀ ਹੋਈ ਹੈ। ਲਿਖਤੀ ਸਮਝੌਤੇ ਅਤੇ ਆਪਣੇ ਬਾਜ਼ਾਰ ਤੋਂ ਬਿਨਾਂ ਸ਼ੁਰੂ ਨਾ ਕਰੋ।',
    'mr': '❌ **"परत खरेदी करू" च्या आश्वासनावर महागडी पिल्ले घेणे** — एमूमध्ये हीच सर्वात मोठी फसवणूक झाली आहे. लेखी करार आणि स्वतःच्या बाजाराशिवाय सुरू करू नका.',
    'bho': '❌ **"वापस खरीद लेब" के वादा पर महँगा चूजा लेल** — एमू में इहे सबसे बड़ ठगी भइल बा। लिखित समझौता आ अपना बजार के बिना मत शुरू करीं।',
  },
};
